export function initOhlecHUD() {
  console.log('[OHLEC HUD] Initializing...');

  // Initially, Step 0 (Initialization) automatically transitions to Step 1
  // We can update the UI wizard state
  setStep(1);

  // You can add event listeners for the specific OHLEC UI components here
  // For example, buttons in the Contextual Action Panel
}

export function setStep(stepNumber: number) {
  // Reset all steps to inactive/dimmed
  for (let i = 0; i < 5; i++) {
    const stepEl = document.getElementById(`step-${i}`);
    if (stepEl) {
      stepEl.style.opacity = '0.5';
      stepEl.style.background = 'transparent';
      stepEl.style.borderLeft = '3px solid transparent';
    }
  }

  // Highlight the active step
  const activeStep = document.getElementById(`step-${stepNumber - 1}`);
  if (activeStep) {
    activeStep.style.opacity = '1';
    activeStep.style.background = 'rgba(0,255,255,0.1)';
    activeStep.style.borderLeft = '3px solid var(--accent-cyan)';
  }

  // Update contextual text
  const title = document.getElementById('ohlec-action-title');
  const desc = document.getElementById('ohlec-action-desc');
  
  if (!title || !desc) return;

  switch(stepNumber) {
    case 1:
      title.innerText = 'Step 1: Define Objective';
      desc.innerText = 'Identify the safest drop zone for the log segment. Click the ground to place your target zone.';
      break;
    case 2:
      title.innerText = 'Step 2: Hazards Scan';
      desc.innerText = 'Orbit the camera and click to identify all critical hazards (widowmakers, spring poles, etc).';
      break;
    case 3:
      title.innerText = 'Step 3: Leans & Binds';
      desc.innerText = 'Toggle Stress Vision to see internal forces, then classify the bind type.';
      break;
    case 4:
      title.innerText = 'Step 4: Escape Route';
      desc.innerText = 'Draw your intended escape path in the safe 45-degree quadrant.';
      break;
    case 5:
      title.innerText = 'Step 5: Cut Plan';
      desc.innerText = 'Place your virtual cut planes to safely relieve binds without pinching the bar.';
      break;
  }
}
